<template>
  <section class="report-page" v-loading="loading">
    <header class="report-heading"><div><span class="report-label">WEEKLY HEALTH REVIEW</span><h1>你的健康周报</h1><p>{{ periodText }}，看看这一周的记录如何汇成新的节奏。</p></div><el-button icon="el-icon-refresh" @click="loadReport">刷新报告</el-button></header>
    <div v-if="report" class="report-content">
      <section class="report-hero"><div><span class="report-label light">WEEK IN REVIEW</span><h2>{{ report.overview.scoreLevel || '正在生长' }}</h2><p>{{ report.overview.summary }}</p></div><div class="report-score"><strong>{{ String(report.overview.healthScore || 0).padStart(2, '0') }}</strong><span>本周健康分</span></div></section>
      <div class="report-columns">
        <section class="report-section"><header><span class="report-label">MOVEMENT</span><h2>运动轨迹</h2></header><div class="report-stat"><strong>{{ report.overview.weeklyMinutes || 0 }}</strong><span>分钟</span><em>目标150分钟 · 完成{{ movementRate }}%</em></div><div class="mini-progress"><i :style="{ width: movementRate + '%' }" /></div><p class="section-note">{{ movementNote }}</p></section>
        <section class="report-section"><header><span class="report-label">NUTRITION</span><h2>饮食概览</h2></header><div class="report-stat"><strong>{{ dietCalories }}</strong><span>kcal</span><em>近7天平均摄入</em></div><p class="section-note">记录饮食后，报告会继续补充摄入与运动消耗的关系。</p></section>
      </div>
      <section class="report-section health-section"><header><span class="report-label">BODY SIGNALS</span><h2>身体数据变化</h2></header><div v-if="latestHealth" class="health-signal-grid"><div><span>体重</span><strong>{{ latestHealth.weight || '--' }}<small>kg</small></strong></div><div><span>血压</span><strong>{{ latestHealth.systolicPressure || '--' }}<small>/{{ latestHealth.diastolicPressure || '--' }}</small></strong></div><div><span>血糖</span><strong>{{ latestHealth.bloodSugar || '--' }}<small>mmol/L</small></strong></div><div><span>心率</span><strong>{{ latestHealth.heartRate || '--' }}<small>bpm</small></strong></div></div><div v-else class="signal-empty"><i class="el-icon-monitor" /><p>还没有身体数据，记录一次测量后这里会出现趋势。</p><router-link to="/health-data">去记录身体数据 <i class="el-icon-right" /></router-link></div></section>
      <section class="report-section next-week"><div><span class="report-label">NEXT WEEK</span><h2>下周建议</h2><p>把一个小目标放进日程，比等待状态变好更有效。</p></div><div class="suggestion-list"><div v-for="(suggestion,index) in report.overview.suggestions.slice(0,3)" :key="suggestion"><span>0{{ index + 1 }}</span><p>{{ cleanText(suggestion) }}</p></div></div></section>
    </div>
  </section>
</template>
<script>
import { getReportSource } from '@/api/report'
export default { name:'HealthReport', data:()=>({loading:false,report:null}), computed:{periodText(){return new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric'}).format(new Date())},movementRate(){return Math.min(100,Math.round(((this.report&&this.report.overview.weeklyMinutes)||0)/150*100))},movementNote(){const left=Math.max(0,150-((this.report&&this.report.overview.weeklyMinutes)||0));return left?`再完成${left}分钟运动，就能达到本周阶段目标。`:'本周运动目标已经完成，记得安排休息。'},dietCalories(){const value=this.report&&this.report.diet&&this.report.diet.weeklyAvgCalories;return value?Math.round(value):'--'},latestHealth(){const rows=(this.report&&this.report.health)||[];return rows.length?rows[0]:null}},created(){this.loadReport()},methods:{async loadReport(){this.loading=true;try{this.report=await getReportSource()}finally{this.loading=false}},cleanText(value){return String(value||'').replace(/‎/g,'')}}}
</script>
