in-top:12px;font-size:28px;font-weight:500;color:#3f5f4b}.health-signal-grid small{margin-left:4px;font-size:11px;font-weight:400}.signal-empty{padding:30px 0;color:#7e8b82}.signal-empty i{font-size:25px;color:#6d8871}.signal-empty p{display:inline;margin:0 18px}.signal-empty a{color:#6d8871;text-decoration:none;font-size:13px}.next-week{display:grid;grid-template-columns:.7fr 1.3fr;gap:50px;margin-top:6px;border:0}.next-week h2{margin-bottom:7px}.next-week p{color:#7e8b82;font-size:13px;line-height:1.6}.suggestion-list>div{display:grid;grid-template-columns:42px 1fr;gap:12px;padding:12px 0;border-bottom:1px solid #dce5da}.suggestion-list span{color:#6d8871;font-weight:700}.suggestion-list p{margin:0;color:#55645b}@media(max-width:720px){.report-heading{display:block}.report-heading .el-button{margin-top:18px}.report-hero{display:block;padding:28px}.report-score{align-items:flex-start;padding:22px 0 0;margin-top:22px;border-left:0;border-top:1px solid rgba(255,255,255,.25)}.report-columns,.next-week{grid-template-columns:1fr;gap:12px}.health-signal-grid{grid-template-columns:1fr 1fr}.report-stat em{display:none}}
